c011.try_sql:
-- Compare: ROUND rounds, TRUNC cuts (on dates too)
SELECT ROUND(1234.5, -2) AS r, TRUNC(1789, -2) AS t FROM dual;
SELECT SYSDATE AS teraz, TRUNC(SYSDATE) AS polnoc, TRUNC(SYSDATE, 'MM') AS pocz_miesiaca, ROUND(SYSDATE, 'YYYY') AS rok FROM dual;

c200.try_sql:
-- DATE +/- n is a DATE, DATE - DATE is a number of days...
SELECT hire_date + 0.5 AS plus_12h, hire_date - 1 AS dzien_wczesniej, SYSDATE - hire_date AS dni FROM employees;
-- ...and DATE + DATE is an error
SELECT SYSDATE + hire_date FROM employees;

c1203.try_sql:
-- The first returns nothing, the second finds King and Kochhar
SELECT last_name FROM employees e WHERE LOWER(e.last_name) LIKE 'K%';
SELECT last_name FROM employees e WHERE LOWER(e.last_name) LIKE 'k%';

c1204.try_sql:
-- DATE - number works, DATE * 2 does not
SELECT hire_date - 7 AS tydzien_wczesniej FROM employees;
SELECT hire_date * 2 FROM employees;

c1206.try_sql:
-- For 23:30: 1410 minutes, 23.5 hours
WITH t AS (SELECT TO_DATE('2024-05-10 23:30', 'YYYY-MM-DD HH24:MI') AS d FROM dual)
SELECT (d - TRUNC(d)) * 1440 AS minuty, (d - TRUNC(d)) * 24 AS godziny FROM t;
